"""Copy unchanged font/license assets and generate UIContext-scoped registration."""
from eta_port_common import PROJECT, ETA_COMMIT, arguments, emit, emit_json, origin

REGISTRATION = '''// Ported from app/src/main/kotlin/io/github/mangi/eta/ui/components/EtaFonts.kt @ 3b1794d.
// Required Notice: Copyright © 2026 蛮吉 (Mangi-11).
// Generated by scripts/port-eta-assets.py. Body text keeps the system font.
import { UIContext } from '@kit.ArkUI';

export class EtaFontFamilies {
  static readonly Normal: string = 'EtaMonospace';
  static readonly Bold: string = 'EtaMonospaceBold';
}

export function registerEtaFonts(context: UIContext): void {
  const fonts = context.getFont();
  fonts.registerFont({ familyName: EtaFontFamilies.Normal, familySrc: $rawfile('fonts/jetbrains_mono_regular.ttf') });
  fonts.registerFont({ familyName: EtaFontFamilies.Bold, familySrc: $rawfile('fonts/jetbrains_mono_bold.ttf') });
}
'''


def generate(eta_root, output, check=False):
    notice = 'Required Notice: Copyright © 2026 蛮吉 (Mangi-11).'
    license_file = eta_root / 'LICENSE'
    if notice not in license_file.read_text(): raise ValueError('Eta Required Notice missing')
    emit(output / 'LICENSE', license_file.read_bytes(), check)
    raw = output / 'entry/src/main/resources/rawfile'
    pairs = [(license_file, raw / 'licenses/Eta-PolyForm-Noncommercial-1.0.0.txt'),
             (PROJECT / 'scripts/eta-upstream/miuix-0.9.4/LICENSE', raw / 'licenses/Miuix-APACHE-2.0.txt'),
             (PROJECT / 'node_modules/@material-design-icons/svg/LICENSE', raw / 'licenses/Material-Icons-APACHE-2.0.txt'),
             (PROJECT / 'scripts/eta-upstream/JetBrainsMono-OFL.txt', raw / 'licenses/JetBrainsMono-OFL.txt')]
    fonts = []
    for name in ['jetbrains_mono_regular.ttf', 'jetbrains_mono_bold.ttf']:
        source = eta_root / 'app/src/main/res/font' / name
        if source.read_bytes()[:4] not in (b'\x00\x01\x00\x00', b'OTTO'): raise ValueError('Invalid font file')
        pairs.append((source, raw / 'fonts' / name)); fonts.append(origin(source, eta_root))
    for source, destination in pairs: emit(destination, source.read_bytes(), check)
    emit(output / 'entry/src/main/ets/platform/EtaFonts.ets', REGISTRATION, check)
    emit_json(output / 'docs/eta-fonts.json', {'etaCommit': ETA_COMMIT, 'fonts': fonts,
        'registration': 'UIContext.getFont().registerFont; regular and bold use separate family aliases',
        'bodyFont': 'HarmonyOS system font', 'license': 'OFL-1.1; license text from JetBrains/JetBrainsMono v2.304'}, check)


if __name__ == '__main__':
    args = arguments(__doc__); generate(args.eta_root, args.output_root, args.check)
    print('Copied 2 original JetBrains Mono fonts and 4 licenses; generated font registration')
